  Test("rootfix-cooldown-keydown-keeps-held-basic-current-chain",()=>{var c=new ManualControlCore();var p=new Port();Tick(c,p,Frame());var f=Frame();f.AttackHeld=true;Tick(c,p,f);int clears=p.Clears;p.Blocked.Add(1);f.SlotDown=1;for(int i=0;i<50;i++)Tick(c,p,f);Check(p.Calls==1&&p.Chain()&&c.AttackHeld&&c.PendingSlot==0&&p.Clears==clears,"current combo preempted");Console.WriteLine("TRACE cooldown-spam: busy=true held=true pending=0 calls=1 cancelDelta=0");});
