  Test("rootfix-only-successful-ready-skill-has-priority",()=>{var c=new ManualControlCore();var p=new Port();Tick(c,p,Frame());var f=Frame();f.AttackHeld=true;f.SlotDown=1;Tick(c,p,f);Check(p.Calls==1&&p.Slot==1&&!c.AttackHeld,"ready skill priority");p.Busy=false;f.SlotDown=0;Tick(c,p,f);Check(p.Calls==2&&p.Slot==0,"held requires repress");});
  Test("rootfix-runtime-resource-readiness-reject-no-clear-or-motion-stop",()=>{var x=Rig();Update(x.control);x.skills.Blocked.Add(1);int cancels=x.skills.Clears,stops=x.actor.GetComponent<MovementMono>().Stops;Input.MouseHeld=true;Input.mousePosition=new Vector3(9,0,0);Input.Down.Add(KeyCode.Alpha1);Update(x.control);Check(x.skills.Aims.Count==1&&x.skills.Calls[0].slot==0&&x.skills.Clears==cancels&&x.actor.GetComponent<MovementMono>().Stops==stops,"readiness reject preempted");});
  Test("rootfix-invalid-skill-reject-basic-held-continues-next-tick",()=>{var x=Rig();Update(x.control);x.skills.SkillPool.Runtimes[SeojinControlPolicy.Slots[1]].sourceEquipment.AimMode=Skill.SkillAimMode.Invalid;Input.MouseHeld=true;Input.mousePosition=new Vector3(9,0,0);Input.Down.Add(KeyCode.Alpha1);Update(x.control);Input.Down.Clear();Update(x.control);Check(x.skills.Aims.Count==2&&x.skills.Calls.TrueForAll(c=>c.slot==0),"invalid skill held starvation");});
  Test("combo-adapter-reads-current-mouse-each-step",()=>{var x=Rig();x.skills.SkillPool.Runtimes[SeojinControlPolicy.Slots[0]].comboProfile=new Skill.Combo{Enabled=true};Update(x.control);Input.MouseHeld=true;Input.mousePosition=new Vector3(9,0,0);Update(x.control);var read=x.skills.StepAim;Check(read!=null&&x.skills.Aims[0].Direction.x==1,"initial source missing");Check(read().Direction.x==1,"initial commit reread input");Time.frameCount++;Input.mousePosition=new Vector3(-9,0,0);var b=read();Input.mousePosition=new Vector3(0,-9,0);var c=read();Check(b.Direction.x==-1&&b.Direction.y==0&&c.Direction.y==-1,"callback reused whole combo aim");Check(b.Direction.x==-1,"prior value mutated");});
  Test("combo-adapter-no-camera-WASD-and-exact-last-step-fallback",()=>{var x=Rig();x.skills.SkillPool.Runtimes[SeojinControlPolicy.Slots[0]].comboProfile=new Skill.Combo{Enabled=true};Update(x.control);Input.MouseHeld=true;Camera.main=null;Input.Held.Add(KeyCode.W);Update(x.control);Check(x.skills.Aims[0].Direction.x==0&&x.skills.Aims[0].Direction.y==1,"initial invalid ray failed");Input.Held.Clear();var next=x.skills.StepAim();Check(next.Direction.x==0&&next.Direction.y==1,"fallback quantized exact up to diagonal");Input.Held.Add(KeyCode.A);next=x.skills.StepAim();Check(next.Direction.x==-1&&next.Direction.y==0,"current WASD did not override last facing");});
  Test("combo-adapter-cooldown-reject-keeps-existing-provider",()=>{var x=Rig();x.skills.SkillPool.Runtimes[SeojinControlPolicy.Slots[0]].comboProfile=new Skill.Combo{Enabled=true};Update(x.control);Input.MouseHeld=true;Input.mousePosition=new Vector3(9,0,0);Update(x.control);var read=x.skills.StepAim;x.skills.ManualBusy=true;x.skills.Blocked.Add(1);Input.Down.Add(KeyCode.Alpha1);Input.mousePosition=new Vector3(-9,0,0);Update(x.control);Check(ReferenceEquals(read,x.skills.StepAim)&&(++Time.frameCount>0)&&read().Direction.x==-1,"rejection replaced or froze combo provider");});
  foreach(string block in new[]{"UI","pause","auto","transition","disabled"})Test("combo-provider-immediate-"+block+"-blocks-without-input-read",()=>{var x=Rig();x.skills.SkillPool.Runtimes[SeojinControlPolicy.Slots[0]].comboProfile=new Skill.Combo{Enabled=true};Update(x.control);Input.MouseHeld=true;Input.mousePosition=new Vector3(9,0,0);Update(x.control);var camera=Camera.main;int reads=camera.RayReads;if(block=="UI")UnityEngine.EventSystems.EventSystem.current=new UnityEngine.EventSystems.EventSystem{Over=true};if(block=="pause")Time.timeScale=0;if(block=="auto")x.control.SetAutoMode(true);if(block=="transition")Battle.Morpg.BattleMorpgLiveRoute.Locked=true;if(block=="disabled")x.control.enabled=false;Check(!x.skills.StepAim().IsValid&&camera.RayReads==reads,"unauthorized provider sampled before Update");});
  Test("combo-initial-commit-reuses-one-sample",()=>{var x=Rig();x.skills.SkillPool.Runtimes[SeojinControlPolicy.Slots[0]].comboProfile=new Skill.Combo{Enabled=true};Update(x.control);Input.MouseHeld=true;Input.mousePosition=new Vector3(9,0,0);Update(x.control);int reads=Camera.main.RayReads;Input.mousePosition=new Vector3(-9,0,0);Check(x.skills.StepAim().Direction.x==1&&Camera.main.RayReads==reads,"same commit sampled twice");Time.frameCount++;Check(x.skills.StepAim().Direction.x==-1&&Camera.main.RayReads==reads+1,"next step not sampled");});
  Test("combo-delayed-first-commit-resamples-current-frame",()=>{var x=Rig();x.skills.SkillPool.Runtimes[SeojinControlPolicy.Slots[0]].comboProfile=new Skill.Combo{Enabled=true};Update(x.control);Input.MouseHeld=true;Input.mousePosition=new Vector3(9,0,0);Update(x.control);Time.frameCount++;Input.mousePosition=new Vector3(-9,0,0);Check(x.skills.StepAim().Direction.x==-1,"delayed first start used stale aim");});
  Test("UI-suspension-cancels-active-generation-before-handback",()=>{var x=Rig();Update(x.control);int cancels=x.skills.Clears;UnityEngine.EventSystems.EventSystem.current=new UnityEngine.EventSystems.EventSystem{Over=true};Update(x.control);Check(x.skills.Clears==cancels+1,"UI only cleared held without canceling coroutine epoch");});
  Console.WriteLine("PASS "+count+"/"+count+" production input/core/control lifecycle tests");
 }
